 @Test void revokedQaQualificationBlocksReleaseDespiteRetainedPermission(){
  var pending=completedQaBatch();
  as(qa);
  var qualifiedReview=finishedQa.review(id(pending));
  assertThat(qualifiedReview.path("allowedActions").toString()).contains("\"RELEASE\"");
  permissions.add("master:qualification:update");
  as(author);
  Long qualificationId=jdbc.queryForObject("SELECT id FROM md_qualification WHERE org_id=1 AND user_id=? AND qualification_code='IQ_INCOMING_IT'",Long.class,qa);
  qualificationAdministration.command(Long.toString(qualificationId),
    new com.hospital.mes.masterdata.application.QualificationCommands.Update("DISABLE","Controlled test credential revocation",0L,null,null),"\"0\"",key());
  as(qa);
  var restrictedReview=finishedQa.review(id(pending));
  assertThat(restrictedReview.path("allowedActions").toString()).doesNotContain("\"RELEASE\"");
  var command=releaseCommand(pending,"RELEASED",null);
  blockedCode("QUALIFICATION_REQUIRED",()->finishedQa.decide(command,token(pending),key()));
  assertThat(finishedDecisions.decisions(1,Long.parseLong(id(pending)))).isEmpty();
  assertThat(production.batch(id(pending)).path("status").asText()).isEqualTo("PENDING_QA");
 }
