 protected JsonNode completedQaBatch(){return completedQaBatch(()->{});}
 protected JsonNode completedQaBatch(Runnable beforeCompletion){var completed=completedProductionBatch(beforeCompletion);completeFinishedQuality(completed);as(qa);return production.submitQa(id(completed),body("reason","Actual upstream facts submitted for QA"),token(completed),key());}
 protected JsonNode completedProductionBatch(Runnable beforeCompletion){
  var batch=approvedBatch();String bid=id(batch),eid=batch.path("executionUnits").get(0).path("id").asText();var op=executionService.operations(eid).getFirst();op=executionService.start(id(op),body("reason","Actual manufacturing operation"),token(op),key());
  String formula=productionQuery.batch(1,Long.parseLong(bid)).snapshot().path("process").path("formula").path("items").get(0).path("formulaItemId").asText();var scale=equipment.create(new EquipmentCommands.Create("QA_SC"+suffix,"Actual weighing scale","PRODUCTION_IT_SCALE",LocalDate.now(ZoneOffset.UTC).plusDays(30),"Production"),key());var exec=production.execution(eid);
  var weighed=weighing.createWeighing(body("executionUnitId",eid,"materialLotId",lot,"formulaItemId",formula,"targetQty","2","actualQty","2","unitId",unit,"scaleEquipmentId",id(scale),"versionNo",exec.path("versionNo").asLong(),"reason","Actual frozen BOM weighing"),key());as(reviewer);weighed=weighing.verifyWeighing(id(weighed),body("reason","Independent weighing verification","reauthToken","token"),token(weighed),key());as(author);
  weighing.createCharge(body("executionUnitId",eid,"operationExecutionId",id(op),"materialLotId",lot,"weighingRecordId",id(weighed),"chargedQty","2","unitId",unit,"versionNo",op.path("versionNo").asLong(),"reason","Actual material charge"),key());
  var current=production.batch(bid);quantities.record(bid,output(current,"QA_OUTPUT"+suffix,"10"),token(current),key());observation(production.batch(bid),"QA_LOSS"+suffix,"0");calculate(production.batch(bid));
  var sample=productionQuality.createSample(body("investigationScope","PRODUCTION","mainBatchId",bid,"sampleNo","QA_SAMPLE"+suffix,"sampleType","TEST_SAMPLE","materialLotId",production.batch(bid).path("finishedLotId").asText(),"quantity","1","unitId",unit,"sourceRef","QA_SRC"+suffix,"reason","Actual finished QC sample"),key());sample=productionQuality.receiveSample(id(sample),body("versionNo",0,"reason","Actual QC receipt"),token(sample),key());String item=productionQuery.batch(1,Long.parseLong(bid)).snapshot().path("qualityPlan").path("specification").path("items").get(0).path("specificationItemId").asText();var test=productionQuality.createTest(body("sampleId",id(sample),"specificationItemId",item,"reason","Test frozen required assay"),key());test=productionQuality.result(id(test),false,body("versionNo",0,"resultNumeric","2","reason","Original assay result","signature",Map.of("reauthToken","token")),token(test),key());as(reviewer);productionQuality.review(id(test),body("versionNo",test.path("versionNo").asLong(),"resultRevisionId",test.path("currentResultRevisionId").asText(),"disposition","CONFIRMED","reason","Independent assay review","signature",Map.of("reauthToken","token")),token(test),key());as(author);
  beforeCompletion.run();recordAndSubmitOperationForm(eid);var latest=executionService.operation(1,Long.parseLong(id(op)));executionService.complete(id(latest),body("reason","Actual eBR and charge complete"),token(latest),key());var completed=production.completeProduction(bid,body("reason","All actual production and balance gates complete"),token(production.batch(bid)),key());return completed;
 }
 protected JsonNode releaseCommand(JsonNode batch,String decision,JsonNode predecessor){var review=finishedQa.review(id(batch));var b=body("mainBatchId",id(batch),"finishedLotId",batch.path("finishedLotId").asText(),"versionNo",review.path("versionNo").asLong(),"decision",decision,"releaseBasis","FULL_INSPECTION","reviewDigest",review.path("reviewDigest").asText(),"reason","Independent final QA decision","signature",Map.of("reauthToken","token"));if(predecessor!=null)((com.fasterxml.jackson.databind.node.ObjectNode)b).put("supersedesDecisionId",id(predecessor));return b;}
 @Test void realBatchLifecycleReleaseIsAtomicSignedIdempotentAndMakesFinishedInventoryAvailable(){var pending=completedQaBatch();String bid=id(pending),flot=pending.path("finishedLotId").asText();assertThat(stockQuery.materialLot(1,Long.parseLong(flot)).path("qualityStatus").asText()).isEqualTo("QUARANTINE");var command=releaseCommand(pending,"RELEASED",null);String k=key();var decision=finishedQa.decide(command,token(pending),k);assertThat(finishedQa.decide(command,token(pending),k)).isEqualTo(decision);assertThat(production.batch(bid).path("status").asText()).isEqualTo("QA_RELEASED");assertThat(stockQuery.materialLot(1,Long.parseLong(flot)).path("qualityStatus").asText()).isEqualTo("RELEASED");assertThat(stockQuery.materialLot(1,Long.parseLong(flot)).path("inventoryStatus").asText()).isEqualTo("AVAILABLE");assertThat(verifier.verify(1,decision.path("signatureId").asLong())).isTrue();assertThat(finishedDecisions.decisions(1,Long.parseLong(bid))).hasSize(1);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM integration_outbox WHERE aggregate_type='ReleaseDecision' AND aggregate_id=?",Long.class,id(decision))).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM mes_genealogy WHERE main_batch_id=?",Long.class,bid)).isEqualTo(1);assertThatThrownBy(()->jdbc.update("UPDATE qms_release_decision SET reason='tamper' WHERE id=?",id(decision))).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void changedDisplayedEvidencePermissionAndIndependentQaBlockWithoutDecision(){var pending=completedQaBatch();var command=releaseCommand(pending,"RELEASED",null);((com.fasterxml.jackson.databind.node.ObjectNode)command).put("reviewDigest","0".repeat(64));rejected(com.hospital.mes.common.exception.ResourceConflictException.class,()->finishedQa.decide(command,token(pending),key()));as(author);var self=releaseCommand(pending,"RELEASED",null);blockedCode("QA_INDEPENDENT_REQUIRED",()->finishedQa.decide(self,token(pending),key()));permissions.remove("qa:release");as(qa);rejected(com.hospital.mes.common.exception.PermissionException.class,()->finishedQa.decide(self,token(pending),key()));as(qa);assertThat(finishedDecisions.decisions(1,Long.parseLong(id(pending)))).isEmpty();assertThat(production.batch(id(pending)).path("status").asText()).isEqualTo("PENDING_QA");}
 @Test void auditFailureRollsBackDecisionSignatureAvailabilityAndOutbox(){var pending=completedQaBatch();var command=releaseCommand(pending,"RELEASED",null);String k=key();long sig=jdbc.queryForObject("SELECT COUNT(*) FROM gxp_signature",Long.class);org.mockito.Mockito.doAnswer(inv->{var a=(com.hospital.mes.audit.domain.AuditCommand)inv.getArgument(0);if(a.objectType().equals("ReleaseDecision")&&a.action().equals("FINISHED_QA_RELEASED"))throw new IllegalStateException("Injected final QA audit failure");return inv.callRealMethod();}).when(audit).append(org.mockito.ArgumentMatchers.any());rejected(IllegalStateException.class,()->finishedQa.decide(command,token(pending),k));assertThat(finishedDecisions.decisions(1,Long.parseLong(id(pending)))).isEmpty();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM gxp_signature",Long.class)).isEqualTo(sig);assertThat(stockQuery.materialLot(1,pending.path("finishedLotId").asLong()).path("qualityStatus").asText()).isEqualTo("QUARANTINE");assertThat(production.batch(id(pending)).path("status").asText()).isEqualTo("PENDING_QA");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM platform_idempotency_record WHERE idempotency_key=?",Long.class,k)).isZero();org.mockito.Mockito.reset(audit);var d=finishedQa.decide(command,token(pending),k);assertThat(verifier.verify(1,d.path("signatureId").asLong())).isTrue();}
 @Test void actualGateChangeInvalidatesDisplayedReviewAndRejectNeedsNoFabricatedPassingGate(){var pending=completedQaBatch();var stale=releaseCommand(pending,"RELEASED",null);as(author);productionQuality.createDeviation(body("investigationScope","PRODUCTION","mainBatchId",id(pending),"investigationKind","DEVIATION","severity","CRITICAL","description","Actual late critical finding after QA submission","reason","Document actual new QA evidence"),key());as(qa);rejected(com.hospital.mes.common.exception.ResourceConflictException.class,()->finishedQa.decide(stale,token(pending),key()));var latest=releaseCommand(pending,"RELEASED",null);blockedCode("RELEASE_GATE_FAILED",()->finishedQa.decide(latest,token(pending),key()));assertThat(finishedDecisions.decisions(1,Long.parseLong(id(pending)))).isEmpty();var rejection=releaseCommand(pending,"REJECTED",null);var d=finishedQa.decide(rejection,token(pending),key());assertThat(d.path("decision").asText()).isEqualTo("REJECTED");assertThat(stockQuery.materialLot(1,pending.path("finishedLotId").asLong()).path("inventoryStatus").asText()).isEqualTo("BLOCKED");}
 @Test void reviewActionsHonorIndependentQaSupersession(){
  var pending=completedQaBatch();
  var first=finishedQa.decide(releaseCommand(pending,"RELEASED",null),token(pending),key());
  as(qa);
  var sameSigner=finishedQa.review(id(pending));
  assertThat(sameSigner.path("allowedActions")).isEmpty();
  as(approver);
  var independentSigner=finishedQa.review(id(pending));
  assertThat(independentSigner.path("allowedActions").toString()).contains("\"REJECT\"");
  assertThat(finishedDecisions.decisions(1,Long.parseLong(id(pending)))).hasSize(1);
  assertThat(verifier.verify(1,first.path("signatureId").asLong())).isTrue();
 }
 @Test void explicitIndependentSupersessionPreservesEveryOriginalDecisionAndSignature(){var pending=completedQaBatch();var original=finishedQa.decide(releaseCommand(pending,"RELEASED",null),token(pending),key());var released=production.batch(id(pending));var absent=releaseCommand(released,"REJECTED",null);rejected(com.hospital.mes.common.exception.ResourceConflictException.class,()->finishedQa.decide(absent,token(released),key()));var own=releaseCommand(released,"REJECTED",original);blockedCode("QA_INDEPENDENT_REQUIRED",()->finishedQa.decide(own,token(released),key()));as(approver);var successor=finishedQa.decide(releaseCommand(released,"REJECTED",original),token(released),key());assertThat(successor.path("supersedesDecisionId").asText()).isEqualTo(id(original));assertThat(finishedQa.get(id(original))).isEqualTo(original);assertThat(verifier.verify(1,original.path("signatureId").asLong())).isTrue();assertThat(verifier.verify(1,successor.path("signatureId").asLong())).isTrue();assertThat(finishedDecisions.decisions(1,Long.parseLong(id(pending)))).hasSize(2);assertThat(stockQuery.materialLot(1,pending.path("finishedLotId").asLong()).path("qualityStatus").asText()).isEqualTo("REJECTED");var rejectedBatch=production.batch(id(pending));as(qa);var restored=finishedQa.decide(releaseCommand(rejectedBatch,"RELEASED",successor),token(rejectedBatch),key());assertThat(restored.path("supersedesDecisionId").asText()).isEqualTo(id(successor));assertThat(finishedDecisions.decisions(1,Long.parseLong(id(pending)))).hasSize(3);}
 @Test void actualCompetingQaCommandCannotBypassRootLockOrCreateDecision() throws Exception {var pending=completedQaBatch();var command=releaseCommand(pending,"RELEASED",null);long establishedActor=jdbc.queryForObject("SELECT MIN(id) FROM sys_user",Long.class);org.mockito.Mockito.when(contexts.current()).thenReturn(new com.hospital.mes.audit.application.CurrentPlatformContext(1,establishedActor,Set.of("INCOMING_TEST"),permissions,"incoming-session","contending-qa"));try(var worker=java.util.concurrent.Executors.newSingleThreadExecutor()){var task=worker.submit(()->{var tx=new org.springframework.transaction.support.TransactionTemplate(transactions);tx.setPropagationBehavior(org.springframework.transaction.TransactionDefinition.PROPAGATION_REQUIRES_NEW);tx.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_READ_UNCOMMITTED);return tx.execute(status->{int old=jdbc.queryForObject("SELECT @@innodb_lock_wait_timeout",Integer.class);jdbc.execute("SET SESSION innodb_lock_wait_timeout=1");try{finishedQa.decide(command,token(pending),key());return (RuntimeException)null;}catch(RuntimeException e){return e;}finally{status.setRollbackOnly();jdbc.execute("SET SESSION innodb_lock_wait_timeout="+old);}});});assertThat(task.get(10,java.util.concurrent.TimeUnit.SECONDS)).isInstanceOfSatisfying(com.hospital.mes.common.exception.ResourceConflictException.class,e->assertThat(e.code()).isEqualTo("CONCURRENT_MODIFICATION"));}as(qa);assertThat(finishedDecisions.decisions(1,Long.parseLong(id(pending)))).isEmpty();assertThat(production.batch(id(pending)).path("status").asText()).isEqualTo("PENDING_QA");}
