 @Test void pairedInventoryMovementIsNotConsumptionButPhysicalRemovalBlocksRetroactiveRejection(){var pending=completedQaBatch();permissions.addAll(Set.of("wms:inventory:move","wms:inventory:adjust"));as(qa);var original=finishedQa.decide(releaseCommand(pending,"RELEASED",null),token(pending),key());String finishedLot=pending.path("finishedLotId").asText();var lotView=stockQuery.materialLot(1,Long.parseLong(finishedLot));String sourceLocation=stockQuery.ledger(1,Long.parseLong(finishedLot)).getFirst().path("locationId").asText();var warehouse=wms.maintenance("Warehouse",null,new com.hospital.mes.wms.domain.WmsCommands.WarehouseCreate("QMWH"+suffix,"Finished QA movement","FINISHED"),null,key());var destination=wms.maintenance("Location",null,new com.hospital.mes.wms.domain.WmsCommands.LocationCreate(id(warehouse),"QMLOC"+suffix,"Actual destination"),null,key());wms.move(new com.hospital.mes.wms.domain.WmsCommands.InventoryMove(finishedLot,sourceLocation,null,id(destination),null,"1",unit,lotView.path("versionNo").asLong(),"Actual paired warehouse movement"),token(lotView),key());var batch=production.batch(id(pending));as(approver);var rejected=finishedQa.decide(releaseCommand(batch,"REJECTED",original),token(batch),key());batch=production.batch(id(pending));as(qa);var restored=finishedQa.decide(releaseCommand(batch,"RELEASED",rejected),token(batch),key());lotView=stockQuery.materialLot(1,Long.parseLong(finishedLot));wms.adjust(new com.hospital.mes.wms.domain.WmsCommands.InventoryAdjust(finishedLot,id(destination),null,"-1",unit,lotView.path("versionNo").asLong(),"Actual documented physical removal"),token(lotView),key());var current=production.batch(id(pending));as(approver);var command=releaseCommand(current,"REJECTED",restored);blockedCode("FINISHED_RELEASE_CONSUMED",()->finishedQa.decide(command,token(current),key()));assertThat(production.batch(id(pending)).path("status").asText()).isEqualTo("QA_RELEASED");assertThat(finishedDecisions.decisions(1,Long.parseLong(id(pending)))).hasSize(3);assertThat(verifier.verify(1,restored.path("signatureId").asLong())).isTrue();}
 @Test void actualLateOriginalFailOpensOosAndBlocksFinalQaWithoutOverwritingOriginal() throws Exception {JsonNode[] test=new JsonNode[1];var pending=completedQaBatch(()->{var batchId=jdbc.queryForObject("SELECT id FROM prd_main_batch WHERE batch_no=?",Long.class,"PB"+suffix).toString();var sample=productionQuality.createSample(body("investigationScope","PRODUCTION","mainBatchId",batchId,"sampleNo","QA_EXTRA"+suffix,"sampleType","TEST_SAMPLE","quantity","1","unitId",unit,"sourceRef","QA_CHECK"+suffix,"reason","Additional real QC sample before completion"),key());sample=productionQuality.receiveSample(id(sample),body("versionNo",0,"reason","Actual sample receipt"),token(sample),key());String item=productionQuery.batch(1,Long.parseLong(batchId)).snapshot().path("qualityPlan").path("specification").path("items").get(0).path("specificationItemId").asText();test[0]=productionQuality.createTest(body("sampleId",id(sample),"specificationItemId",item,"reason","Additional real assay instance"),key());});var stale=releaseCommand(pending,"RELEASED",null);var invalidId=stale.deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)invalidId).put("mainBatchId","0"+id(pending));rejected(IllegalArgumentException.class,()->finishedQa.decide(invalidId,token(pending),key()));var missingSignature=stale.deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)missingSignature).remove("signature");rejected(IllegalArgumentException.class,()->finishedQa.decide(missingSignature,token(pending),key()));as(author);var fail=productionQuality.result(id(test[0]),false,body("versionNo",0,"resultNumeric","5","reason","Actual late original failing assay","signature",Map.of("reauthToken","token")),token(test[0]),key());as(qa);assertThat(finishedQa.review(id(pending)).path("blockingCodes")).anySatisfy(code->assertThat(code.asText()).isEqualTo("PRODUCTION_OOS_UNRESOLVED"));rejected(com.hospital.mes.common.exception.ResourceConflictException.class,()->finishedQa.decide(stale,token(pending),key()));var current=releaseCommand(pending,"RELEASED",null);blockedCode("RELEASE_GATE_FAILED",()->finishedQa.decide(current,token(pending),key()));as(author);blockedCode("RESULT_CORRECTION_FORBIDDEN",()->productionQuality.result(id(fail),true,body("versionNo",fail.path("versionNo").asLong(),"previousRevisionId",fail.path("currentResultRevisionId").asText(),"resultNumeric","2","reason","Original failure must remain","signature",Map.of("reauthToken","token")),token(fail),key()));assertThat(jdbc.queryForObject("SELECT result_conclusion FROM qms_test_result_revision WHERE id=?",String.class,fail.path("currentResultRevisionId").asText())).isEqualTo("FAIL");assertThat(finishedDecisions.decisions(1,Long.parseLong(id(pending)))).isEmpty();assertThat(stockQuery.materialLot(1,pending.path("finishedLotId").asLong()).path("qualityStatus").asText()).isEqualTo("QUARANTINE");var readModel=finishedArchive.get(id(pending));FrozenSchemaAssertions.assertSchema(json,"BatchEbrReadModel",readModel);assertThat(readModel.path("qcTests")).anySatisfy(t->assertThat(t.path("results")).anySatisfy(r->assertThat(r.path("resultConclusion").asText()).isEqualTo("FAIL")));assertThat(readModel.path("deviations")).anySatisfy(d->{assertThat(d.path("investigationKind").asText()).isEqualTo("OOS");assertThat(d.path("originalResultRevisionId").asText()).isEqualTo(fail.path("currentResultRevisionId").asText());});var copy=finishedArchive.generate(id(pending),new com.hospital.mes.release.domain.ArchiveCommand(pending.path("versionNo").asLong(),"REVIEW_COPY","Original FAIL and unresolved OOS review copy"),token(pending),key());var bytes=finishedAttachments.readContent(1,copy.path("fileId").asLong()).content();try(var pdf=org.apache.pdfbox.Loader.loadPDF(bytes)){assertThat(new org.apache.pdfbox.text.PDFTextStripper().getText(pdf)).contains("FAIL","OOS");}assertThat(copy.path("archiveKind").asText()).isEqualTo("REVIEW_COPY");}
